from __future__ import annotations
import contextlib
import io
import json
import sys
from types import ModuleType

SOURCE = '#!/usr/bin/env python3\n# -*- coding: utf-8 -*-\n"""Cortex-M 内存与栈预算。\n\n回答"这点 RAM 够不够、栈给多大"这类问题。算的是**预算下限**，\n真值要用实测水位（填充魔数法或调试器测量）确认。\n\n用法:\n    python stack_budget.py --task app=1024:2 --task shell=512 --tcb 96 \\\n        --heap 8K --ram 128K --isr-depth 4 --fpu \\\n        --kernel-path 2K --task-peak app=700 --task-peak shell=320\n    python stack_budget.py --task main=2K --ram 20K --json\n\n口径说明:\n  - Cortex-M 上异常（中断/SVC）一律使用 MSP；任务使用 PSP（若有 RTOS）。\n    因此中断现场与内核处理路径的占用要算进 **MSP**，不是任务栈。\n  - 启用 FPU 时异常入栈使用扩展帧 104 字节（已含基本帧的 32 字节）。\n  - AAPCS 要求公开接口处 SP 8 字节对齐；用 --align 可覆盖（如 MPU 区域 32）。\n\n退出码: 0=ok, 1=warn, 2=error\n"""\n\n\n\nimport argparse\nimport json\nimport sys\nfrom dataclasses import dataclass, field\n\nBASIC_FRAME = 32       # 基本异常入栈帧 8 words\nFPU_FRAME = 104        # 扩展帧 26 words（含基本帧）\n\n\ndef parse_bytes(text: str, what: str) -> int:\n    s = str(text).strip().replace("_", "")\n    if not s:\n        raise ValueError(f"{what}: 空的字节数")\n    mult = 1\n    if s[-1] in "kK":\n        mult, s = 1024, s[:-1]\n    elif s[-1] in "mM":\n        mult, s = 1024 * 1024, s[:-1]\n    try:\n        val = int(float(s) * mult)\n    except ValueError:\n        raise ValueError(f"{what}: 无法解析字节数 {text!r}（支持 1024 / 8K / 1M）")\n    if val < 0:\n        raise ValueError(f"{what}: 字节数不能为负")\n    return val\n\n\ndef align_up(n: int, a: int) -> int:\n    return (n + a - 1) // a * a\n\n\n@dataclass\nclass Task:\n    name: str\n    stack: int\n    count: int = 1\n    peak: int | None = None\n\n    @property\n    def block(self) -> int:\n        return self.stack * self.count\n\n\ndef parse_task(spec: str) -> Task:\n    if "=" not in spec:\n        raise ValueError(f"--task 需要 NAME=STACK[:COUNT] 形式，收到 {spec!r}")\n    name, rhs = spec.split("=", 1)\n    name = name.strip()\n    if not name:\n        raise ValueError("--task 的任务名不能为空")\n    parts = rhs.split(":")\n    stack = parse_bytes(parts[0], f"任务 {name} 的栈大小")\n    count = 1\n    if len(parts) > 1 and parts[1].strip():\n        try:\n            count = int(parts[1])\n        except ValueError:\n            raise ValueError(f"任务 {name} 的个数 {parts[1]!r} 不是整数")\n    if count < 1:\n        raise ValueError(f"任务 {name} 的个数必须 >= 1")\n    return Task(name=name, stack=stack, count=count)\n\n\ndef parse_peak(spec: str) -> tuple[str, int]:\n    if "=" not in spec:\n        raise ValueError(f"--task-peak 需要 NAME=BYTES 形式，收到 {spec!r}")\n    name, val = spec.split("=", 1)\n    return name.strip(), parse_bytes(val, f"任务 {name} 的峰值栈")\n\n\ndef main(argv: list[str] | None = None) -> int:\n    ap = argparse.ArgumentParser(description="Cortex-M 内存与栈预算")\n    ap.add_argument("--task", action="append", default=[], required=True,\n                    help="NAME=STACK[:COUNT]，可多次")\n    ap.add_argument("--tcb", default="96", help="每任务 TCB 字节数，默认 96")\n    ap.add_argument("--heap", default="0", help="堆字节数，默认 0")\n    ap.add_argument("--ram", default=None, help="目标可用 RAM 总量，给了才算余量")\n    ap.add_argument("--isr-depth", type=int, default=0, help="最深中断嵌套层数")\n    ap.add_argument("--isr-frame", default=None, help=f"每层现场字节，默认 {BASIC_FRAME}")\n    ap.add_argument("--fpu", action="store_true",\n                    help=f"启用 FPU：未显式给 --isr-frame 时用扩展帧 {FPU_FRAME}")\n    ap.add_argument("--kernel-path", default="0",\n                    help="SVC/内核处理路径（如文件系统调用）最深使用量，必须实测")\n    ap.add_argument("--task-peak", action="append", default=[],\n                    help="NAME=BYTES 实测/估算峰值栈，可多次；用于校验栈是否够")\n    ap.add_argument("--fill-margin", type=float, default=0.30,\n                    help="栈余量比例，默认 0.30")\n    ap.add_argument("--align", default="8", help="对齐字节，默认 8（MPU 区域可用 32）")\n    ap.add_argument("--json", action="store_true")\n    args = ap.parse_args(argv)\n\n    try:\n        tasks = [parse_task(s) for s in args.task]\n        names = [t.name for t in tasks]\n        if len(set(names)) != len(names):\n            raise ValueError("--task 里有重名任务")\n        for name, val in (parse_peak(s) for s in args.task_peak):\n            hit = next((t for t in tasks if t.name == name), None)\n            if hit is None:\n                raise ValueError(f"--task-peak 指向不存在的任务 {name!r}")\n            hit.peak = val\n        tcb = parse_bytes(args.tcb, "--tcb")\n        heap = parse_bytes(args.heap, "--heap")\n        kernel_path = parse_bytes(args.kernel_path, "--kernel-path")\n        align = parse_bytes(args.align, "--align")\n        ram = parse_bytes(args.ram, "--ram") if args.ram else None\n        isr_frame = parse_bytes(args.isr_frame, "--isr-frame") if args.isr_frame else \\\n            (FPU_FRAME if args.fpu else BASIC_FRAME)\n    except ValueError as exc:\n        print(f"参数错误：{exc}", file=sys.stderr)\n        return 2\n\n    if args.isr_depth < 0:\n        print("参数错误：--isr-depth 不能为负", file=sys.stderr)\n        return 2\n    if not (0 <= args.fill_margin < 10):\n        print("参数错误：--fill-margin 应在 [0, 10) 之间", file=sys.stderr)\n        return 2\n\n    rows = []\n    warnings: list[str] = []\n    notes: list[str] = []\n\n    for t in tasks:\n        alloc = align_up(t.block + tcb * t.count, align)\n        need = None\n        if t.peak is not None:\n            need = align_up(int(t.peak * (1.0 + args.fill_margin)), align)\n            if need > t.stack:\n                warnings.append(\n                    f"任务 {t.name}：栈 {t.stack} B 小于「峰值 {t.peak} B + "\n                    f"{args.fill_margin:.0%} 余量」所需的 {need} B")\n        rows.append({"task": t.name, "stack": t.stack, "count": t.count,\n                     "peak": t.peak, "block": t.block, "tcb": tcb * t.count,\n                     "alloc": alloc, "need": need})\n\n    isr = args.isr_depth * isr_frame\n    msp = align_up(isr + kernel_path, align)\n    if args.isr_depth and kernel_path == 0:\n        notes.append("中断已计入但 --kernel-path 为 0：SVC/内核路径（文件系统、"\n                     "协议栈等）的 MSP 使用量必须实测，不能按 0 计")\n    if args.isr_depth and isr_frame == FPU_FRAME:\n        notes.append(f"按 FPU 扩展帧 {FPU_FRAME} B/层计（含基本帧 {BASIC_FRAME} B）")\n\n    total = sum(r["alloc"] for r in rows) + msp + heap\n    free = ram - total if ram is not None else None\n\n    verdict = "ok"\n    if ram is not None:\n        if total > ram:\n            verdict = "error"\n            warnings.append(f"总占用 {total} B 超过 RAM {ram} B，超出 {total - ram} B")\n        elif free < ram * 0.15:\n            verdict = "warn"\n            warnings.append(f"RAM 余量仅 {free} B（{free / ram:.1%}），建议留 >= 15%")\n    if warnings and verdict == "ok":\n        verdict = "warn"\n\n    if args.json:\n        print(json.dumps({\n            "verdict": verdict, "align": align, "tcb": tcb, "heap": heap,\n            "isr_depth": args.isr_depth, "isr_frame": isr_frame,\n            "isr_reserve": isr, "kernel_path": kernel_path, "msp_reserve": msp,\n            "tasks": rows, "total": total, "ram": ram, "free": free,\n            "warnings": warnings, "notes": notes,\n        }, ensure_ascii=False, indent=2))\n        return {"ok": 0, "warn": 1, "error": 2}[verdict]\n\n    print(f"对齐 {align} B / TCB {tcb} B / 堆 {heap} B")\n    print(f"{\'任务\':<16}{\'栈 B\':>8}{\'个数\':>6}{\'峰值 B\':>9}{\'对齐后 B\':>10}{\'建议下限\':>10}")\n    print("-" * 62)\n    for r in rows:\n        peak = "-" if r["peak"] is None else str(r["peak"])\n        need = "-" if r["need"] is None else str(r["need"])\n        print(f"{r[\'task\']:<16}{r[\'stack\']:>8}{r[\'count\']:>6}{peak:>9}"\n              f"{r[\'alloc\']:>10}{need:>10}")\n    print("-" * 62)\n    print(f"任务区合计（含 TCB）：{sum(r[\'alloc\'] for r in rows)} B")\n    print(f"MSP 预留：{msp} B  （{args.isr_depth} 层 x {isr_frame} B"\n          f" + 内核路径 {kernel_path} B）")\n    print(f"堆：{heap} B")\n    print(f"总计：{total} B" + (f" / RAM {ram} B，余量 {free} B"\n                                f"（{free / ram:.1%}）" if ram is not None else ""))\n    print(f"verdict: {verdict}")\n    for w in warnings:\n        print(f"  ! {w}")\n    for n in notes:\n        print(f"  · {n}")\n    print("  → 预算是下限保障；结论请用实测栈水位确认")\n    return {"ok": 0, "warn": 1, "error": 2}[verdict]\n\n\nif __name__ == "__main__":\n    raise SystemExit(main())\n'

def main():
    capture, errors = io.StringIO(), io.StringIO()
    code = 0
    try:
        request = json.load(sys.stdin)
        args = request.get('args')
        if not isinstance(args, list) or any(not isinstance(x, str) for x in args):
            raise ValueError('args_must_be_string_list')
        sys.argv = ['stack_budget.py'] + args
        module = ModuleType('__main__')
        module.__file__ = 'stack_budget.py'
        sys.modules['__main__'] = module
        with contextlib.redirect_stdout(capture), contextlib.redirect_stderr(errors):
            exec(compile(SOURCE, 'stack_budget.py', 'exec'), module.__dict__)
    except SystemExit as error:
        code = error.code if isinstance(error.code, int) else 1
    except Exception as error:
        code = 1
        errors.write(type(error).__name__ + ': ' + str(error))
    print(json.dumps({'exit_code': code, 'stdout': capture.getvalue(), 'stderr': errors.getvalue()}, ensure_ascii=False))
    return code

if __name__ == '__main__':
    raise SystemExit(main())
